/* From Uiverse.io by ahmed150up - Tags: card, chat, chatgpt */
.__UIV_SCOPE__ .chat-card {
  width: 300px;
  background-color: #fff;
  border-radius: 5px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  overflow: hidden;
}

.__UIV_SCOPE__ .chat-header {
  padding: 10px;
  background-color: #f2f2f2;
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .chat-header .h2 {
  font-size: 16px;
  color: #333;
}

.__UIV_SCOPE__ .chat-body {
  padding: 20px;
}

.__UIV_SCOPE__ .message {
  margin-bottom: 10px;
  padding: 10px;
  border-radius: 5px;
}

.__UIV_SCOPE__ .incoming {
  background-color: #e1e1e1;
}

.__UIV_SCOPE__ .outgoing {
  background-color: #f2f2f2;
  text-align: right;
}

.__UIV_SCOPE__ .message p {
  font-size: 14px;
  color: #333;
  margin: 0;
}

.__UIV_SCOPE__ .chat-footer {
  padding: 10px;
  background-color: #f2f2f2;
  display: flex;
}

.__UIV_SCOPE__ .chat-footer input[type="text"] {
  flex-grow: 1;
  padding: 5px;
  border: none;
  border-radius: 3px;
}

.__UIV_SCOPE__ .chat-footer button {
  padding: 5px 10px;
  border: none;
  background-color: #4285f4;
  color: #fff;
  font-weight: bold;
  cursor: pointer;
  transition: background-color 0.3s;
}

.__UIV_SCOPE__ .chat-footer button:hover {
  background-color: #0f9d58;
}

@keyframes chatAnimation {
  0% {
    opacity: 0;
    transform: translateY(10px);
  }

  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

.__UIV_SCOPE__ .chat-card .message {
  animation: chatAnimation 0.3s ease-in-out;
  animation-fill-mode: both;
  animation-delay: 0.1s;
}

.__UIV_SCOPE__ .chat-card .message:nth-child(even) {
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .chat-card .message:nth-child(odd) {
  animation-delay: 0.3s;
}
